import{_ as a,o as t,c as n,a5 as s}from"./chunks/framework.pJebtgMf.js";const m=JSON.parse('{"title":"AI 动态 · 2026-08-15","description":"","frontmatter":{"title":"AI 动态 · 2026-08-15","date":"2026-08-15T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-15.md","filePath":"news/2026-08/ai-news-2026-08-15.md","lastUpdated":null}'),r={name:"news/2026-08/ai-news-2026-08-15.md"};function o(i,e,p,l,c,h){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-08-15" tabindex="-1">AI 动态 · 2026-08-15 <a class="header-anchor" href="#ai-动态-·-2026-08-15" aria-label="Permalink to &quot;AI 动态 · 2026-08-15&quot;">​</a></h1><blockquote><p>截至 2026-08-15。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="google-允许用户移除-ai-生成内容的可见水印" tabindex="-1">Google 允许用户移除 AI 生成内容的可见水印 <a class="header-anchor" href="#google-允许用户移除-ai-生成内容的可见水印" aria-label="Permalink to &quot;Google 允许用户移除 AI 生成内容的可见水印&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-15">2026-08-15</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/8fb9ae5a0e70.jpg" alt="配图"></p><p>Google 宣布允许用户移除 Gemini、Flow 等 AI 工具生成图片、视频和音乐中的可见“闪光”水印。该开关不影响底层的 SynthID 隐形水印和 C2PA 元数据，后者仍用于识别 AI 生成内容。此功能适用于 Nano Banana、Omni 和 Lyria 模型。对读者：移除可见水印可提升内容观感，但隐形标识仍可溯源，使用 AI 内容时需注意合规与透明性。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/14/google-will-now-allow-users-to-remove-visible-watermark-from-its-ai-generations/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="亚马逊可用-twitch-内容训练-ai-用户需主动选择退出" tabindex="-1">亚马逊可用 Twitch 内容训练 AI，用户需主动选择退出 <a class="header-anchor" href="#亚马逊可用-twitch-内容训练-ai-用户需主动选择退出" aria-label="Permalink to &quot;亚马逊可用 Twitch 内容训练 AI，用户需主动选择退出&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Wired AI</span><time datetime="2026-08-15">2026-08-15</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/645f68d208b7.jpg" alt="配图"></p><p>Twitch 更新账户设置，允许主播选择退出将其内容用于训练亚马逊的 AI 模型。但此举引发大量创作者质疑：平台何时开始使用用户直播、视频和帖子进行训练，以及为何默认是“选择加入”而非“选择退出”。目前亚马逊未明确说明数据使用的起始时间和具体范围。对读者：创作者应尽快检查 Twitch 账户设置，按需关闭 AI 训练授权，保护自身内容权益。</p><p class="news-entry-source"><a href="https://www.wired.com/story/amazon-uses-your-twitch-content-to-train-its-ai-how-to-opt-out/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="ibm-与-openai-达成合作-加码企业级-ai-市场" tabindex="-1">IBM 与 OpenAI 达成合作，加码企业级 AI 市场 <a class="header-anchor" href="#ibm-与-openai-达成合作-加码企业级-ai-市场" aria-label="Permalink to &quot;IBM 与 OpenAI 达成合作，加码企业级 AI 市场&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/060dfe13e050.jpg" alt="配图"></p><p>IBM 宣布与 OpenAI 建立合作伙伴关系，计划培训和认证数万名顾问掌握 OpenAI 技术，并共同营销 AI 产品、开发行业特定解决方案。此举是 IBM 在不到一年内继与 Anthropic 结盟后的又一重大动作，反映出企业 AI 市场竞争白热化，OpenAI 正通过咨询巨头触达全球大型企业客户。对读者：企业采购 AI 服务时将有更多集成选项，可关注 IBM 咨询渠道带来的 OpenAI 模型落地案例。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/13/ibm-partners-with-openai-to-bolster-enterprise-ai-push/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai-任命新任首席营收官-高管层持续动荡" tabindex="-1">OpenAI 任命新任首席营收官，高管层持续动荡 <a class="header-anchor" href="#openai-任命新任首席营收官-高管层持续动荡" aria-label="Permalink to &quot;OpenAI 任命新任首席营收官，高管层持续动荡&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/1a3d6f54f091.jpg" alt="配图"></p><p>OpenAI 在首席营收官 Denise Dresser 上任仅九个月后将其替换，任命 Wiz 总裁兼首席运营官 Dali Rajic 担任此职。此前一个月内，COO Brad Lightcap 和 AGI 部署 CEO Fidji Simo 已相继离职，联合创始人 Greg Brockman 则承担更多管理职责。这一系列变动显示 OpenAI 正经历重大组织调整。对读者：关注 OpenAI 高管变动可能带来的产品策略与商业化方向变化，企业客户需留意合作稳定性。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/13/openai-hires-new-cro-as-executive-shake-up-continues/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="openai-推出-ultrafast-模式-gpt-5-6-sol-提速-14-倍" tabindex="-1">OpenAI 推出 Ultrafast 模式，GPT-5.6 Sol 提速 14 倍 <a class="header-anchor" href="#openai-推出-ultrafast-模式-gpt-5-6-sol-提速-14-倍" aria-label="Permalink to &quot;OpenAI 推出 Ultrafast 模式，GPT-5.6 Sol 提速 14 倍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/63e1b5275da5.jpg" alt="配图"></p><p>OpenAI 发布 Ultrafast 模式预览版，使最新旗舰模型 GPT-5.6 Sol 的处理速度提升至标准模式的 14 倍，每秒可输出高达 750 个 token。该功能旨在吸引对响应速度要求极高的企业用户，解决大模型在实时交互场景中的延迟痛点。对读者：若你的应用对延迟敏感，可关注 Ultrafast 模式的开放范围与定价，评估是否接入以提升用户体验。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/13/openai-introduces-ultrafast-a-new-mode-that-makes-gpt-5-6-sol-work-at-14x-the-speed/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="gemini-3-7-flash-发布-三周迭代-主打编程与-agent" tabindex="-1">Gemini 3.7 Flash 发布：三周迭代，主打编程与 Agent <a class="header-anchor" href="#gemini-3-7-flash-发布-三周迭代-主打编程与-agent" aria-label="Permalink to &quot;Gemini 3.7 Flash 发布：三周迭代，主打编程与 Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/5735a04e1057.png" alt="配图"></p><p>Google DeepMind 发布 Gemini 3.7 Flash，定位为“迄今最智能的主力模型”，重点面向编程和 Agent 场景。该模型距 3.6 Flash 发布仅三周，且紧随 DeepMind 权力重组八天。新领导 Koray Kavukcuoglu 已实质接管 Gemini 全栈研发。快速迭代反映谷歌正加速工程化节奏，并针对开发者反馈进行算法创新。对读者：开发者可关注 Gemini 3.7 Flash 在 Coding 与 Agent 任务上的性能表现，评估是否迁移工作流。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/plZY01etBHv3ETOYG0af?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="deepseek-发布-v4-pro-定价最高达-v4-flash-的-14-倍" tabindex="-1">DeepSeek 发布 V4 Pro，定价最高达 V4 Flash 的 14 倍 <a class="header-anchor" href="#deepseek-发布-v4-pro-定价最高达-v4-flash-的-14-倍" aria-label="Permalink to &quot;DeepSeek 发布 V4 Pro，定价最高达 V4 Flash 的 14 倍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Reuters</span><time datetime="2026-08-14">2026-08-14</time></p><p>DeepSeek 正式推出 V4 Pro 模型，其 API 定价最高可达 V4 Flash 的 14 倍。这一价格策略显示 DeepSeek 正在细分产品线：Flash 版本主打高性价比和缓存命中率，Pro 版本则面向对性能要求更高的企业级任务。此前社区测试显示 DeepSeek V4 Flash 在 Pi Harness 中缓存命中率可达 99% 以上，成本优势显著。对读者：根据任务复杂度选择合适的模型版本，高频简单任务可继续使用 Flash 以控制成本。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMirgFBVV95cUxNVzBOcmxUZXZzV20xU1pZMnI1X0JKRzV1SUJwcGhzaE1JZDZfUTZqVDZMVXNhUHFoY295SHZuLWZZbTlXa1AtUmI2dkRhRWliRXFBYzdZQlROdUVzZ2dNc2pHLUhvdTFBSVpSTW9SaHBQUnJubTdMX2FQUkhHTDhiUGtiZDUxLTRQXzRrZERqSzlOSXZpMWYxUzVWeXFCdW1HZEVWbWMtVDhFU1BCSkE?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="智谱-glm-5-3-发布-对标-openai-与-anthropic-前沿模型" tabindex="-1">智谱 GLM-5.3 发布，对标 OpenAI 与 Anthropic 前沿模型 <a class="header-anchor" href="#智谱-glm-5-3-发布-对标-openai-与-anthropic-前沿模型" aria-label="Permalink to &quot;智谱 GLM-5.3 发布，对标 OpenAI 与 Anthropic 前沿模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">International Business Times</span><time datetime="2026-08-15">2026-08-15</time></p><p>中国 AI 公司 Z.ai 发布 GLM-5.3 模型，宣称在编程等能力上对标 Anthropic 的 Mythos 和 OpenAI 的旗舰模型。该模型具备高级网络能力，据报道已发现 Cursor 的严重漏洞。多家外媒关注其发布时机与策略，认为中国 AI 实验室正加速追赶全球前沿水平。对读者：可关注 GLM-5.3 在编程与 Agent 场景的实测表现，作为闭源模型之外的国产替代选项。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMiogFBVV95cUxNWV9fakJGRzFrVTFlSnVNbm1QWThsUjhDMjl1UjNrREVOZmxkeFAzdVRESHJKaHNXdFJGZkVZVC0zX2hGbmxBM24xeXN6X0Vpa0Jland5WkpoX3ZiQWFjWnRmeE9tRndDTG5BYlphdnh2WjF1dC1JVlFfZ3N5MXNGeXZmNWFBRWxaOE56X0pZSUJQNzFSaWx2U1pLTGdXelR5dkE?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="qwen3-8-27b-开源-消费级显卡可跑-多项-agent-评测超-claude" tabindex="-1">Qwen3.8-27B 开源：消费级显卡可跑，多项 Agent 评测超 Claude <a class="header-anchor" href="#qwen3-8-27b-开源-消费级显卡可跑-多项-agent-评测超-claude" aria-label="Permalink to &quot;Qwen3.8-27B 开源：消费级显卡可跑，多项 Agent 评测超 Claude&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-15">2026-08-15</time></p><p>阿里开源 Qwen3.8-27B，总参数量 27B，支持原生多模态、262K 上下文（可扩展至 100 万 Token）。官方 Benchmark 显示其在 SWE-bench Pro 上以 8.3 分优势超过 Claude Opus 4.6 Max，QwenSWEBench 领先 15.2 分。经量化后可在 24GB 显存的 RTX 3090/4090 上本地运行，实现“Opus 级”Agent 能力。对读者：开发者可在本地部署该模型处理编程与长程 Agent 任务，降低 API 依赖与数据隐私风险。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/473669.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="deepseek-harness-插件生态爆发-github-仓库超-700-个" tabindex="-1">DeepSeek Harness 插件生态爆发：GitHub 仓库超 700 个 <a class="header-anchor" href="#deepseek-harness-插件生态爆发-github-仓库超-700-个" aria-label="Permalink to &quot;DeepSeek Harness 插件生态爆发：GitHub 仓库超 700 个&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-15">2026-08-15</time></p><p>DeepSeek Harness 开源 Agent 框架发布后，GitHub 上 dsh-plugin 标签的公开仓库已超 700 个。社区开发者为其开发了浏览器、长期记忆、数据库、任务管理、视觉模型接入等实用插件，甚至包括电子宠物、小游戏和 2005 年风格广告 UI 等趣味扩展。其“Everything is a Plugin”架构极大激发了社区创造力。对读者：可关注 Awesome DeepSeek Harness Plugins 精选目录，快速找到提升 Agent 工作流的实用插件。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/473597.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="soup-一个-yaml-配置微调-llm-4gb-显卡可训练-8b-模型" tabindex="-1">Soup：一个 YAML 配置微调 LLM，4GB 显卡可训练 8B 模型 <a class="header-anchor" href="#soup-一个-yaml-配置微调-llm-4gb-显卡可训练-8b-模型" aria-label="Permalink to &quot;Soup：一个 YAML 配置微调 LLM，4GB 显卡可训练 8B 模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MakazhanAlpamys/Soup</span><time datetime="2026-08-15">2026-08-15</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/2b3a0b2d6a84.png" alt="配图"></p><p>开源项目 Soup 允许用户通过单个 YAML 文件微调大语言模型。其核心创新是层流式训练（layer streaming）技术，使得在仅有 4GB 显存的笔记本 GPU 上即可训练 8B 参数模型，大幅降低了模型微调的硬件门槛。对读者：个人开发者和小团队可尝试用 Soup 在消费级硬件上完成模型定制，无需依赖昂贵云 GPU。</p><p class="news-entry-source"><a href="https://github.com/MakazhanAlpamys/Soup" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="github-推出四款-agent-应用-覆盖软件交付全流程" tabindex="-1">GitHub 推出四款 Agent 应用，覆盖软件交付全流程 <a class="header-anchor" href="#github-推出四款-agent-应用-覆盖软件交付全流程" aria-label="Permalink to &quot;GitHub 推出四款 Agent 应用，覆盖软件交付全流程&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-08-15">2026-08-15</time></p><p>GitHub 博客介绍了四个 Agent 应用，帮助开发者在 GitHub 平台内完成软件交付生命周期的关键环节：范围界定、安全加固、发布和交付。这些 Agent 应用旨在减少上下文切换，让团队无需离开 GitHub 即可完成从需求到上线的整个流程，提升软件交付效率。对读者：团队可评估这些 Agent 应用与现有 CI/CD 流程的集成度，探索在单一平台内闭环管理开发工作流。</p><p class="news-entry-source"><a href="https://github.blog/ai-and-ml/github-copilot/how-to-bring-your-software-delivery-workflow-into-github-with-agent-apps/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="pi-harness-deepseek-组合跑赢-claude-code-成本仅为-1-7" tabindex="-1">Pi Harness + DeepSeek 组合跑赢 Claude Code，成本仅为 1/7 <a class="header-anchor" href="#pi-harness-deepseek-组合跑赢-claude-code-成本仅为-1-7" aria-label="Permalink to &quot;Pi Harness + DeepSeek 组合跑赢 Claude Code，成本仅为 1/7&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-14">2026-08-14</time></p><p>Composio 公开测试显示，同一 DeepSeek V4 Flash 模型在不同 Agent Harness 中表现差异巨大：Pi Agent 以 66.7% 成功率排名第一，Claude Code 为 53.3%。成本方面，Pi 完成一项成功任务平均仅需 0.028 美元，约为 Claude Code（0.195 美元）的七分之一。Pi 的缓存命中率可达 99% 以上，显著降低重复 token 成本。对读者：Agent 的 Harness 选择与模型同等重要，建议对比测试不同框架再决定技术栈。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/XpFUaftcEE3iLgGzYGZi?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="codex-与-claude-code-负责人公开互怼-coding-agent-竞争转向-harness" tabindex="-1">Codex 与 Claude Code 负责人公开互怼，Coding Agent 竞争转向 Harness <a class="header-anchor" href="#codex-与-claude-code-负责人公开互怼-coding-agent-竞争转向-harness" aria-label="Permalink to &quot;Codex 与 Claude Code 负责人公开互怼，Coding Agent 竞争转向 Harness&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-14">2026-08-14</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/57713e988370.png" alt="配图"></p><p>OpenAI Codex 负责人 Tibo 公开引导用户将 GPT-5.6 Sol 注入 Claude Code 运行，Anthropic 随后封禁照做的开发者账号，引发双方负责人隔空交锋。事件核心争议在于 Coding Agent 的竞争焦点正从模型能力转向执行框架（Harness）——同一模型在不同 Harness 中表现差异显著。对读者：选择 Coding Agent 时不应只看模型，需综合评估 Harness 的工具链、权限模型与生态兼容性。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/YWXm26HRwC9ySEGZ9Lpp?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
